def build_agent(sandbox):
    # Main beam within build zone
    main_beam = sandbox.add_beam(x=4.5, y=1.5, width=0.4, height=3.0, density=10.0)

    # Add two more beams within the build zone
    beam1 = sandbox.add_beam(x=4.5, y=3.5, width=0.4, height=3.0, density=10.0)
    beam2 = sandbox.add_beam(x=4.5, y=5.0, width=0.4, height=3.0, density=10.0)

    # Pads
    pad_right = sandbox.add_pad(x=4.5 + 0.2, y=1.5, radius=0.12, density=5.0)
    pad_left = sandbox.add_pad(x=4.5 - 0.2, y=1.5, radius=0.12, density=5.0)

    # Joints connecting pads to main beam
    joint_right = sandbox.add_joint(main_beam, pad_right, (4.5 + 0.2, 1.5), type='pivot')
    joint_left = sandbox.add_joint(main_beam, pad_left, (4.5 - 0.2, 1.5), type='pivot')

    return {
        'main_beam': main_beam,
        'pads': [pad_right, pad_left],
        'joints': [joint_right, joint_left]
    }

def agent_action(sandbox, agent_body, step_count):
    pads = agent_body.get('pads', [])
    joints = agent_body.get('joints', [])

    # Control cycle for alternating pad activation and motor torque
    cycle = 4
    phase = step_count % cycle

    # Activate pads based on phase
    if phase == 0 or phase == 2:
        sandbox.set_pad_active(pads[0], True)
        sandbox.set_pad_active(pads[1], False)
    else:
        sandbox.set_pad_active(pads[0], False)
        sandbox.set_pad_active(pads[1], True)

    # Apply motor torque to the appropriate joint
    if phase == 0 or phase == 2:
        sandbox.set_motor(joints[0], motor_speed=5.0, max_torque=100.0)
    else:
        sandbox.set_motor(joints[1], motor_speed=5.0, max_torque=100.0)
